metadados.consulta_graphql:
query RepositoriosPopulares($primeiros: Int!, $cursor: String, $busca: String!) {
  rateLimit {
    limit
    cost
    remaining
    resetAt
  }
  search(query: $busca, type: REPOSITORY, first: $primeiros, after: $cursor) {
    repositoryCount
    pageInfo {
      hasNextPage
      endCursor
    }
    nodes {
      ... on Repository {
        nameWithOwner
        url
        stargazerCount
        pushedAt
        updatedAt
        defaultBranchRef {
          name
          target {
            ... on Commit {
              committedDate
            }
          }
        }
        primaryLanguage {
          name
        }
        pullRequestsAceitos: pullRequests(first: 1, states: MERGED) {
          totalCount
        }
        releases(first: 1) {
          totalCount
        }
      }
    }
  }
}
